export enum EventType {
  CASAMENTO = 'Casamento',
  FESTA = 'Festa',
  CORPORATIVO = 'Corporativo',
  OUTROS = 'Outros'
}

export interface Package {
  id: string;
  name: string;
  price: string;
  currency: string;
  features: string[];
  color: string;
  tagline: string;
}

export interface CustomerOrder {
  packageId: string;
  date: string;
  name: string;
  email: string;
  phone: string;
  notes?: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getAiEventSuggestion(eventType: string, guestCount: number, preferences: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Sugira um conceito de decoração de luxo para um evento de ${eventType} para ${guestCount} pessoas. Preferências do cliente: ${preferences}. Foque em tons elegantes (dourado, nude, branco). Retorne uma sugestão curta e inspiradora.`,
      config: {
        systemInstruction: "Você é um consultor de eventos de luxo da Avaeventos. Seu tom é sofisticado, poético e profissional.",
        temperature: 0.7,
      },
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Não conseguimos gerar uma sugestão agora, mas nossa equipe terá prazer em criar algo único para você!";
  }
}

import React, { useState, useEffect } from 'react';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${isScrolled ? 'bg-white shadow-md py-3' : 'bg-transparent py-6'}`}>
      <div className="container mx-auto px-6 flex justify-between items-center">
        <a href="#" className={`text-2xl font-bold tracking-widest ${isScrolled ? 'text-gray-900' : 'text-white'}`}>
          AVA<span className="text-gold">EVENTOS</span>
        </a>

        <div className="hidden md:flex space-x-8 items-center">
          <a href="#sobre" className={`hover:text-gold transition ${isScrolled ? 'text-gray-700' : 'text-white'}`}>Sobre</a>
          <a href="#galeria" className={`hover:text-gold transition ${isScrolled ? 'text-gray-700' : 'text-white'}`}>Galeria</a>
          <a href="#pacotes" className={`hover:text-gold transition ${isScrolled ? 'text-gray-700' : 'text-white'}`}>Pacotes</a>
          <a href="#orcamento" className="bg-gold text-white px-6 py-2 rounded-full hover:bg-opacity-90 transition">Orçamento</a>
        </div>

        <button className="md:hidden text-gold">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
          </svg>
        </button>
      </div>
    </nav>
  );
};

export default Navbar;

