            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>

        {step === 1 ? (
          <form onSubmit={handleSubmit} className="p-8">
            <h2 className="text-3xl font-bold mb-2">Reserva do {pkg.name}</h2>
            <p className="text-gray-500 mb-8">Preencha os dados para garantir sua data.</p>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Nome Completo</label>
                <input 
                  required
                  type="text" 
                  className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-gold outline-none"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">WhatsApp</label>
                <input 
                  required
                  type="tel" 
                  className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-gold outline-none"
                  placeholder="+244"
                  value={formData.phone}
                  onChange={e => setFormData({...formData, phone: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Data do Evento</label>
                <input 
                  required
                  type="date" 
                  className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-gold outline-none"
                  value={formData.date}
                  onChange={e => setFormData({...formData, date: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Forma de Pagamento</label>
                <select 
                  className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-gold outline-none"
                  value={formData.paymentMethod}
                  onChange={e => setFormData({...formData, paymentMethod: e.target.value})}
                >
                  <option>Transferência Bancária</option>
                  <option>Pagamento Local (Sede)</option>
                  <option>Cartão de Crédito/Débito</option>
                </select>
              </div>
            </div>

            <div className="mt-10 p-4 bg-gray-50 rounded-2xl flex justify-between items-center">
              <div>
                <p className="text-xs text-gray-500 uppercase tracking-widest">Total a pagar</p>
                <p className="text-xl font-bold">{pkg.currency} {pkg.price}</p>
              </div>
