import React, { useState } from 'react';
import { getAiEventSuggestion } from '../services/gemini';

const AIAssistant: React.FC = () => {
  const [eventType, setEventType] = useState('Casamento');
  const [guests, setGuests] = useState(100);
  const [pref, setPref] = useState('');
  const [suggestion, setSuggestion] = useState('');
  const [loading, setLoading] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    const res = await getAiEventSuggestion(eventType, guests, pref);
    setSuggestion(res);
    setLoading(false);
  };

  return (
    <section id="ai-assistant" className="py-24 bg-gold bg-opacity-5">
      <div className="container mx-auto px-6 max-w-4xl bg-white p-10 rounded-3xl shadow-xl border border-gold border-opacity-20">
        <div className="text-center mb-10">
          <span className="bg-gold text-white text-xs font-bold px-4 py-1 rounded-full uppercase mb-4 inline-block">Novidade: AI Avaeventos</span>
          <h2 className="text-3xl md:text-4xl font-bold mb-4">Planeje o Conceito do seu Evento</h2>
          <p className="text-gray-600">Nossa inteligência artificial sugere temas exclusivos baseados nos seus desejos.</p>
        </div>

        <div className="grid md:grid-cols-2 gap-6 mb-8">
          <div>
            <label className="block text-sm font-semibold mb-2">Tipo de Evento</label>
            <select 
              className="w-full p-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-gold outline-none"
              value={eventType}
              onChange={e => setEventType(e.target.value)}
            >
              <option>Casamento</option>
              <option>Festa de 15 Anos</option>
              <option>Evento Corporativo</option>
              <option>Aniversário</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-semibold mb-2">Número de Convidados</label>
            <input 
              type="number" 
              className="w-full p-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-gold outline-none"
              value={guests}
              onChange={e => setGuests(Number(e.target.value))}
            />
          </div>
        </div>

        <div className="mb-8">
          <label className="block text-sm font-semibold mb-2">Suas Preferências (Cores, Estilos, Flores...)</label>
          <textarea 
            className="w-full p-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-gold outline-none h-24"
            placeholder="Ex: Quero algo rústico mas elegante, com muitas peônias brancas e velas."
            value={pref}
            onChange={e => setPref(e.target.value)}
          ></textarea>
        </div>

        <button 
          onClick={handleGenerate}
          disabled={loading}
          className="w-full bg-gold text-white py-4 rounded-xl font-bold hover:bg-opacity-90 transition disabled:opacity-50"
        >
          {loading ? 'Gerando Inspiração...' : 'Gerar Conceito Exclusivo'}
        </button>

        {suggestion && (
          <div className="mt-10 p-6 bg-gold bg-opacity-10 rounded-2xl border-l-4 border-gold italic text-gray-700 leading-relaxed">
            "{suggestion}"
          </div>
        )}
      </div>
    </section>
  );
};

export default AIAssistant;

